import re

def fill_spaces(s):
    return re.sub(r'[ ,.]', ':', s)

def recur_gcd(a, b):
    if b == 0:
        return a
    else:
        return recur_gcd(b, a % b)

def next_smallest_palindrome(n):
    n += 1
    while not is_palindrome(n):
        n += 1
    return n

def is_palindrome(n):
    return str(n) == str(n)[::-1]

def exchange_elements(lst):
    n = 2  # You can change this value to any number you want
    return [lst[i] if i % n != 0 else lst[i-1] for i in range(len(lst))]

def divisor(n):
    count = 0
    for i in range(1, n + 1):
        if n % i == 0:
            count += 1
    return count

import re

def is_allowed_specific_char(s):
    pattern = r'^[a-zA-Z0-9]+$'
    return bool(re.match(pattern, s))

def round_and_sum(numbers):
    total = sum(round(num) for num in numbers)
    return total * len(numbers)

def max_char(s):
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    return max(char_count, key=char_count.get)

def recursive_list_sum(lst):
    total = 0
    for element in lst:
        if isinstance(element, list):
            total += recursive_list_sum(element)
        else:
            total += element
    return total

def overlapping(seq1, seq2):
    for elem in seq1:
        if elem in seq2:
            return True
    return False

def subject_marks(tuples_list):
    return sorted(tuples_list, key=lambda x: x[1])

