def find_tuples(tuples, k):
    result = []
    for t in tuples:
        if all(i % k == 0 for i in t):
            result.append(str(t))
    return '[' + ', '.join(result) + ']'

def list_to_float(lst):
    result = []
    for element in lst:
        try:
            result.append((float(element[0]), float(element[1])))
        except ValueError:
            pass
    return str(result)

def lucky_num(n):
    lucky_numbers = []
    num = 2
    while len(lucky_numbers) < n:
        is_lucky = True
        for digit in str(num):
            if digit in '456':
                is_lucky = False
                break
        if is_lucky:
            lucky_numbers.append(num)
        num += 1
    return lucky_numbers

def count_Fac(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def prime_factors(num):
        factors = set()
        for i in range(2, num + 1):
            if num % i == 0 and is_prime(i):
                factors.add(i)
        return factors

    factors = prime_factors(n)
    return len(factors)

