def last_Digit_Factorial(n):
    if n == 0:
        return 1
    elif n == 1:
        return 1
    else:
        last_digit = 1
        for i in range(2, n + 1):
            last_digit = (last_digit * i) % 10
        return last_digit

def get_Inv_Count(arr, x):
    inv_count = 0
    for i in range(len(arr)):
        for j in range(i+1, len(arr)):
            if arr[i] > x and arr[j] <= x:
                inv_count += 1
    return inv_count

def max_sub_array_sum(arr, target_sum):
    max_length = 0
    current_sum = 0
    left = 0

    for right in range(len(arr)):
        current_sum += arr[right]

        while current_sum > target_sum and left <= right:
            current_sum -= arr[left]
            left += 1

        if current_sum == target_sum:
            max_length = max(max_length, right - left + 1)

    return max_length

def find_Max_Len_Even(sentence):
    words = sentence.split()
    max_len = 0
    max_len_word = ""
    for word in words:
        if len(word) % 2 == 0 and len(word) > max_len:
            max_len = len(word)
            max_len_word = word
    return max_len_word
